        }

        Xpj42 sale = saleBid.getSale();
        if (sale == null) {
            throw new Xzj75Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }




    private Xtw92 createInstantOrderBid(Xhq12 order, Xzt63 saleBid, Xpj42 sale) {
        Xcc44 productSize = saleBid.getProductSize();

        Xtw92 orderBid = Xtw92.builder()
                .user(order.getUser())
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(Xkh73Status.MATCHED)
                .order(order)
                .sale(sale)
                .build();


        orderBid.assignOrder(order);


        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }




    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof Xhq12Exception) {
            throw (Xhq12Exception) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new Xrd49Exception(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }








    @Transactional
    public void matchOrderBid(Xtw92 orderBid) {
        try {
            if (orderBid == null) {
                throw new Xsb40Exception("주문 입찰 정보가 없습니다.");
            }

            if (orderBid.getStatus() == Xkh73Status.MATCHED) {
                throw new Xcw90Exception("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
            }

            orderBid.updateStatus(Xkh73Status.MATCHED);
        } catch (Exception e) {
            if (e instanceof Xhq12Exception) {
                throw e;
            }
            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
            throw new Xfb77Exception("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }









    @Transactional
    public void deleteOrderBid(Long orderBidId) {
        try {

            Xtw92 orderBid = orderBidRepository.findById(orderBidId)
                    .orElseThrow(() -> new Xsb40Exception("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));


            if (orderBid.getSale() != null) {
                throw new Xcw90Exception("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
            }


            if (orderBid.getStatus() == Xkh73Status.MATCHED) {
                throw new Xcw90Exception("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
            }


            if (orderBid.getOrder() != null) {
                orderCommandService.deleteOrder(orderBid.getOrder().getId());
            }


            orderBidRepository.delete(orderBid);
        } catch (Exception e) {
            if (e instanceof Xhq12Exception) {
                throw e;
            }
            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new Xzs26Exception("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
}

